 @Autowired MutableClock time;@Autowired cn.pawday.booking.ServiceTradeService tradeService;
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 UUID store,merchantId,adminSession;String merchant,reader,user,other,foreign,admin;
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String identity(boolean consumer,UUID m,UUID st,List<String> permissions){UUID p=UUID.randomUUID(),role=UUID.randomUUID();String realm=consumer?"CONSUMER":"MERCHANT";
  if(consumer){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,?,?)",p,m,key(),"TEST-ONLY");
  db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,?,?,'BOOKING TEST')",role,realm,key());for(String code:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,code);db.update("INSERT INTO principal_role VALUES (?,?,?)",p,role,realm);
  if(!consumer)db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,m,st);
  String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'BOOKING-IT',?,?,?)",UUID.randomUUID(),p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(604800)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;
 }
 UUID store(UUID m){UUID s=UUID.randomUUID();db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST booking store')",s,m);db.update("INSERT INTO nearby_store_profile(store_id,city,category,address,phone,business_hours,longitude,latitude,services,publication_status,claim_status) VALUES (?,'TEST','GROOMING','TEST address','123456','TEST hours',106,29,'[\"GROOMING\"]','PUBLISHED','VERIFIED')",s);return s;}
 @BeforeEach void setup(){time.current=Instant.now();merchantId=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST booking merchant','ACTIVE')",merchantId);store=store(merchantId);merchant=identity(false,merchantId,store,List.of("store.read","store.nearby.write","service.terms.write","service.trade.read","service.trade.cancel","service.trade.fulfill","service.trade.dispute.read","service.trade.ledger.read"));reader=identity(false,merchantId,store,List.of("store.read"));user=identity(true,null,null,List.of());other=identity(true,null,null,List.of());UUID m=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST foreign','ACTIVE')",m);foreign=identity(false,m,store(m),List.of("store.read","store.nearby.write","service.terms.write","service.trade.read","service.trade.cancel","service.trade.fulfill","service.trade.dispute.read","service.trade.ledger.read"));admin=admin();}
 Response req(String method,String path,Object body,String token,Map<String,String> headers){try{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(30));if(token!=null)builder.header("Authorization","Bearer "+token);headers.forEach(builder::header);builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));if(body!=null)builder.header("Content-Type","application/json");var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());var result=json.readTree(response.body());SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",result));return new Response(response.statusCode(),result);}catch(Exception e){throw new AssertionError(e);}}
 Response get(String path,String token){return req("GET",path,null,token,Map.of());}
 Response post(String path,Object b,String token){return req("POST",path,b,token,Map.of("Idempotency-Key",key()));}
 String services(){return "/merchant/stores/"+store+"/booking-services";}
 String create(){var r=post(services(),Map.of("title","TEST wash","kind","GROOMING"),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Map<String,Object> interval(int seats){Instant start=clock.instant().plus(Duration.ofDays(2)).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);return Map.of("starts_at",start.toString(),"ends_at",start.plusSeconds(3600).toString(),"capacity",seats);}
 String slot(String service,int seats){var r=post("/merchant/booking-services/"+service+"/slots",interval(seats),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Response reserve(String slot,String who,String k){return req("POST","/consumer/service-bookings",Map.of("slot_id",slot),who,Map.of("Idempotency-Key",k));}
 Response cancel(String booking,String who,String k,long v){return req("POST","/consumer/service-bookings/"+booking+"/cancel",Map.of(),who,Map.of("Idempotency-Key",k,"If-Match","\""+v+"\""));}
 Response state(String service,String status,long v){return req("PUT","/merchant/booking-services/"+service+"/state",Map.of("status",status),merchant,Map.of("Idempotency-Key",key(),"If-Match","\""+v+"\""));}


 String admin(){UUID p=UUID.randomUUID(),role=UUID.randomUUID();adminSession=UUID.randomUUID();db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash) VALUES (?,'ADMIN',?,'TEST-ONLY')",p,key());db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,'ADMIN',?,'TEST trade admin')",role,key());db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code IN ('service.terms.review','service.trade.refund.assess','service.trade.refund.review','payment.read','payment.requery','service.trade.dispute.review','service.trade.settle','service.trade.admin.read')",role);db.update("INSERT INTO principal_role VALUES (?,?,'ADMIN')",p,role);String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'TRADE-IT',?,?,?)",adminSession,p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(604800)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;}
 String proof(String action){String token=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,?,?,?)",crypto.hash(token),adminSession,action,Timestamp.from(clock.instant().plusSeconds(300)),Timestamp.from(clock.instant()));return token;}
 Map<String,Object> input(String service,int amount){var b=new LinkedHashMap<String,Object>();b.put("service_id",service);b.put("currency","CNY");b.put("amount_fen",amount);b.put("billing_unit","WHOLE_SLOT");b.put("cancel_cutoff_minutes",60);b.put("consumer_late_cancel","MANUAL_REVIEW");b.put("merchant_cancel","FULL_REFUND");b.put("no_show","MANUAL_REVIEW");b.put("commission_basis_points",333);b.put("settlement_buffer_minutes",120);b.put("evidence_refs",List.of(Map.of("kind","TEST_SCENARIO","reference","TEST_ONLY_B1")));return b;}
 String termsPath(){return "/merchant/stores/"+store+"/service-trade-terms";}
 Response draft(String service,int amount){return post(termsPath(),input(service,amount),merchant);}
 Response review(String id,String who,String proof,String k,long version){return req("POST","/admin/service-trade-terms/"+id+"/review",Map.of("decision","APPROVE_SIMULATION","reason_code","TEST_SCENARIO_REVIEWED"),who,Map.of("X-Reverify-Token",proof,"Idempotency-Key",k,"If-Match","\""+version+"\""));}
 String approved(String service){var d=draft(service,101);assertEquals(200,d.status(),d.body().toString());var r=review(d.id(),admin,proof("service.terms.review"),key(),0);assertEquals(200,r.status(),r.body().toString());return d.id();}
 Response quote(String terms,String slot,String who){return post("/consumer/service-trade-quotes",Map.of("terms_id",terms,"slot_id",slot),who);}
 Response trade(Response quote,String who,String key){return req("POST","/consumer/service-trade-orders",Map.of("quote_id",quote.id(),"accepted_terms_sha256",quote.data().get("terms_sha256").asString()),who,Map.of("Idempotency-Key",key));}
 Response tradeCancel(String id,long v,String who,String key){return req("POST","/consumer/service-trade-orders/"+id+"/cancel",Map.of(),who,Map.of("Idempotency-Key",key,"If-Match","\""+v+"\""));}
 int remaining(String service){return get("/consumer/booking-services/"+service+"/slots",user).data().get(0).get("remaining").asInt();}
 String active(String id){return get("/consumer/service-trade-orders/"+id,user).data().get("order_state").asString();}
 @AfterAll static void samples()throws Exception{Path p=Path.of("target/v313-b3-operations-contract-samples.json");Files.createDirectories(p.getParent());Files.writeString(p,JsonMapper.builder().build().writeValueAsString(SAMPLES));Files.writeString(Path.of("target/v313-b3-schema.json"),JsonMapper.builder().build().writeValueAsString(new JdbcTemplate(PG.getPostgresDatabase()).queryForList("SELECT table_name,column_name,ordinal_position,udt_name,is_nullable,character_maximum_length FROM information_schema.columns WHERE table_schema='public' AND table_name NOT IN ('flyway_schema_history','m63_fixture') ORDER BY table_name,ordinal_position")));}

